"""Current-owner revision landing page, project controls and review assets."""
from pathlib import Path
import json,html
from PIL import Image,ImageDraw,ImageFont
from owner_plan import ROOT,RUN,read_owner

def main():
    e=json.loads((RUN/'materials/estimate.json').read_text(encoding='utf-8'));p=json.loads((RUN/'project/project-plan.json').read_text(encoding='utf-8'));n=json.loads((RUN/'model/native-readback.json').read_text(encoding='utf-8'));m=read_owner(RUN/'plans/C1-owner-linear-100x25.svg');prefix='revisions/owner-brief-v2/';mo=lambda v:f'${v:,.0f}';esc=html.escape
    # Native render montage and stage animation; no AI/generated substitute images.
    font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',22);sheet=Image.new('RGB',(1800,1030),'#faf7ef')
    for i,(name,label) in enumerate([('exterior','Owner brief: split roof and retained walls'),('cutaway','Living / sleeping, service core and garden'),('floor-plan','Three-zone furnished plan'),('structure','Full-span glulam / secondary wood frame')]):
        im=Image.open(RUN/'review'/f'{name}.png').convert('RGB');im.thumbnail((900,475));x=i%2*900;y=i//2*515;sheet.paste(im,(x,y+40));ImageDraw.Draw(sheet).text((x+12,y+8),label,font=font,fill='#233d36')
    sheet.save(RUN/'review/overview.jpg',quality=92)
    frames=[]
    for stage in range(1,15):
        im=Image.open(RUN/'review/stages'/f'{stage:02}.png').convert('RGB');d=ImageDraw.Draw(im);d.rectangle((0,0,im.width,40),fill='#233d36');d.text((12,7),f'{stage:02} / '+json.loads((RUN/'model/assembly-receipt.json').read_text(encoding='utf-8'))['stages'][str(stage)],font=font,fill='white');frames.append(im)
    frames[0].save(RUN/'review/construction.gif',save_all=True,append_images=frames[1:],duration=[800]*13+[2200],loop=0)
    def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    phase_table=table(['Phase','Project weeks','Responsibility','Release condition'],[[r['id']+' / '+r['phase'],f'{r["start_week"]}–{r["end_week"]}' if r['start_week'] else 'After week 72; duration TBD',r['responsible'],r['gate']] for r in p['phases']])
    gate_table=table(['Gate','Required evidence','When','Status'],[[r['id']+' / '+r['hold_point'],r['evidence_needed'],r['when'],r['status']] for r in p['hold_points']])
    req_table=table(['ID / brief requirement','PDF pages','Current status','Implementation / remaining limit'],[[r['id']+' / '+r['requirement'],r['PDF_pages'],r['status'],r['implementation']] for r in p['requirements']])
    source_links=''.join(f'<li><a href="{esc(r["url"])}">{esc(r["title"])}</a> — {esc(r["note"])}</li>' for r in p['sources'])
    project=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner project controls · Portal Earthship V2</title><link rel="stylesheet" href="../../../assets/site.css?v=owner-v2"></head><body><main><nav><a href="../../../index.html">← Current design</a><a href="../materials/costs.html">Construction costs</a><a href="hold-points.csv">Hold-point CSV</a><a href="phase-cash-tracker.csv">Phase cash tracker</a></nav><header><p class="eyebrow">OWNER BRIEF / ALL NINE PAGES REVIEWED</p><h1>Evidence before releases.</h1><p class="lede">Owner approves decisions and payments. PM, design professionals, private inspector and contractors execute the work.</p></header><p class="notice">No APN, permit/disclosure, water/septic approval, insurance acceptance, stamped drawings or field inspection evidence is on file. All nine gates remain UNVERIFIED. These are management records and a conceptual study, not authorization to hire, pay, order or excavate.</p><section><h2>What changed from the ranch study</h2><p>User confirmed the PDF's three-zone layout, 2,500 sf gross including garden and walls, and 50% translucent roof extending over part of the middle zone. C1 100′ × 25′ is provisional; engineer must optimize dimensions to beam and panel supply. C2 83′4″ × 30′ remains a comparison.</p><p>The bathroom is enclosed beneath opaque roof. A glazed garden screen, separate planter drainage, exterior shading, roof vent reservations and humidity-control provision are coordinated concepts. No three-bedroom or all-opaque-roof budget is carried forward.</p><p><b>Backfill sequence conflict:</b> PDF phase 5 precedes roof phase 6. Full backfill requires a stamped temporary restraint/bracing release or completed permanent restraint/diaphragm. Waterproofing acceptance alone is insufficient.</p><p><b>Opt-out:</b> current county guidance says Option 2 provides no Certificate of Occupancy and retains an administrative final site visit. Building-code responsibility and other agency approvals remain. Parcel eligibility and the actual selected option require written records.</p><a href="brief-reconciliation.md">Full reconciliation</a></section><section><h2>Owner phase envelope</h2><p>Weeks 1–72 from project start, followed by closeout. Actual start date and procurement promises are unknown. Construction phases approximately project weeks 22–72; this replaces the earlier 21–37 week construction-only scenario. Gates and supplier dates can extend it.</p>{phase_table}<a href="phase-plan.csv">Download phase plan</a></section><section><h2>Nine mandatory hold points</h2>{gate_table}<p>Signed reports, photos and actual written releases must fill the blank evidence fields. No clearance has been inferred from this model.</p></section><section><h2>Requirements coverage</h2>{req_table}</section><section><h2>Procurement, cash and weekly reporting</h2><p>Three written bids per construction trade; two supplier bids each for glulam and polycarbonate. Written delivery dates, warranties and compatible product details are required. No supplier has been contacted and no bid, contract or payment is fabricated. Orders/awards wait for the stamped package and owner approval.</p><div class="download-list"><a href="procurement-register.csv">Procurement register</a><a href="decision-register.csv">Decision register</a><a href="phase-cash-tracker.csv">Budget / committed / paid tracker</a><a href="weekly-status-template.md">Weekly owner status template</a><a href="contact-log-template.csv">Contact log template</a><a href="requirements-matrix.csv">Requirements CSV</a></div><p>Actual and committed costs remain blank. Contingency percentage awaits bids and owner approval. Reports are local templates; nothing has been sent or scheduled.</p></section><section><h2>Next records needed</h2><p>APN and exact zoning; topo/soils; opt-out/permit and recorded disclosure; water/well-agreement and septic approvals; insurer and professional appointments. Personal source documents stay local. Initial concept work can proceed; physical construction cannot be released by this study.</p><h3>Public sources checked</h3><ul>{source_links}</ul></section><footer>Owner brief SHA256 {p['brief_sha256']} · Source identity retained; raw owner PDF not published.</footer></main></body></html>'''
    (RUN/'project/index.html').write_text(project,encoding='utf-8')
    home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Owner-PDF-aligned 2,500 square foot underground earthship concept near Portal, AZ: three zones, split polycarbonate roof, glulam, project controls and US materials."><title>Portal Earthship · Owner brief V2</title><link rel="stylesheet" href="assets/site.css?v=owner-v2"></head><body><main><nav><a class="brand" href="index.html">PORTAL / EARTHSHIP</a><a href="#plan">Owner layout</a><a href="{prefix}project/index.html">Project controls</a><a href="{prefix}materials/costs.html">Materials & labor</a><a href="#files">Downloads</a><a href="https://github.com/shusain/portal-earthship-home-design">GitHub ↗</a></nav><header class="hero"><div><p class="eyebrow">OWNER PDF REVISION · 2,500 SF GROSS · PROVISIONAL GEOMETRY</p><h1>Three zones.<br>A living garden.<br>One roof span.</h1><p class="lede">A combined living/sleeping zone, central kitchen/bath services, and garden in one earth-retained rectangle. Glulam and wood framing carry a half-opaque, half-polycarbonate roof.</p><span class="status">Three-zone / area / roof split confirmed · dimensions need engineer optimization</span><div class="buttons"><a class="button" href="#plan">Review revised layout</a><a class="button secondary" href="{prefix}project/index.html">Owner hold points</a></div></div><img src="{prefix}review/exterior.png" alt="Native Blender owner-revision rendering with an opaque west roof half and shaded translucent east half" width="1800" height="950"></header><div class="metrics"><article><span>Provisional C1 rectangle</span><strong>100′ × 25′</strong></article><article><span>Gross incl. garden / walls</span><strong>2,500 sq ft</strong></article><article><span>Conservative clear floor</span><strong>2,103 sq ft</strong></article><article><span>Translucent roof fraction</span><strong>50%</strong></article></div><p class="notice">This owner brief supersedes the earlier three-bedroom ranch. Concept only: all approvals and nine hold-point releases are unverified. The roof stays exposed; retained walls and a south daylight/escape court illustrate burial intent without claiming a surveyed site fit. Land/off-grid power acquisition remains excluded.</p><section id="plan"><p class="eyebrow">01 / CONFIRMED BRIEF, PROVISIONAL RECTANGLE</p><h2>1,000 + 700 + 800 gross square feet.</h2><p>The user confirmed the PDF's three zones, 2,500 sf gross including the garden, and 50% translucent roof. Garden occupies 800 sf gross; the remaining 450 sf of the 1,250 sf roof half extends over the middle zone. Bathroom is enclosed under opaque roof. A glazed screen separates garden humidity from the house.</p><a href="{prefix}plans/C1-owner-linear-100x25.svg"><img class="plan" src="{prefix}plans/C1-owner-linear-100x25.svg" alt="C1 owner-revision plan, with 1000, 700 and 800 gross square foot zones, bathroom enclosure, humidity screen, fixtures and roof split" width="1600" height="800"></a><div class="buttons"><a class="button secondary" href="{prefix}plans/C1-owner-linear-100x25.svg">Full SVG plan</a><a class="button secondary" href="{prefix}plans/C1-owner-linear-100x25-rooms.csv">Room areas CSV</a><a href="{prefix}plans/C2-owner-linear-83x30.svg">C2 comparison: 83′4″ × 30′</a></div><p>C1 reduces the gross transverse span to 25 ft, about 22 ft clear between the 18 in exterior assembly reservations. Its length may be unsuitable for a particular parcel. The engineer must compare total roof and retaining costs and revise dimensions to available panel/glulam modules; no cost optimum is claimed.</p></section><section><p class="eyebrow">02 / NATIVE BLENDER STUDY</p><h2>Full-span glulam. Two roof systems.</h2><div class="grid"><figure><img src="{prefix}review/cutaway.png" alt="Three-zone furnished cutaway with enclosed bath and separate planted garden" width="1800" height="950" loading="lazy"><figcaption>One combined living/sleeping zone, central services, garden.</figcaption></figure><figure><img src="{prefix}review/structure.png" alt="Fourteen full transverse glulam beam reservations and secondary roof purlins" width="1800" height="950" loading="lazy"><figcaption>Single-span beam reservations; no interior roof bearing line.</figcaption></figure></div><p>Fourteen beam objects span the short dimension. The modeled 5⅛″ × 18″ section, bearings, 28 ft purchase lengths, purlin sizes and cantilevers are engineering reservations. US dressed timber and stock spacings come from the room-first US framing profile.</p><p>Roof slope is provisionally 10% (1.2″/ft), replacing the old ¼″/ft shed. PC thickness is a supplier 16 mm (~⅝″) reservation. Long panel runs, gasket profiles, the opaque/PC step, thermal expansion, exterior shading and vents need a coordinated manufacturer/engineer detail. Vents are location reservations, not a completed airflow/penetration design.</p><div class="buttons"><a class="button" href="{prefix}model/Owner-Earthship.blend" download>Download revised Blender model</a><a class="button secondary" href="{prefix}review/construction.gif">14-stage assembly reveal</a><a href="{prefix}review/floor-plan.png">Native top view</a></div><details><summary>Geometry checks and limits</summary><p>{n['original_components']} original components; four saved scenes; 14 reveal stages; source/hash identity; closed positive-volume meshes; finite coordinates/unit scale; full-span beam section metrology. Plans check room coverage, fixture containment, conservative complete swings, connected 30″ walking envelopes and interior door pads. None of these checks is engineering, egress certification, site drainage or code approval.</p><a href="{prefix}model/native-readback.json">Native readback</a> · <a href="{prefix}plans/C1-owner-linear-100x25-validation.json">Plan checks</a></details></section><section><p class="eyebrow">03 / BUILD COSTS AND PROJECT TIME</p><h2>Repriced for the owner brief.</h2><div class="metrics"><article><span>Construction materials</span><strong>{mo(e['material_low_usd'])}–{mo(e['material_high_usd'])}</strong></article><article><span>Delegated trade labor</span><strong>{mo(e['labor_low_usd'])}–{mo(e['labor_high_usd'])}</strong></article><article><span>Equipment / temporary works</span><strong>{mo(e['equipment_low_usd'])}–{mo(e['equipment_high_usd'])}</strong></article><article><span>Owner project envelope</span><strong>72 weeks + closeout</strong></article></div><p>Direct construction scenario {mo(e['construction_low_usd'])}–{mo(e['construction_high_usd'])}. Required architecture, engineering, soils, independent inspections and delegated PM are separate additional allowances, {mo(e['mandatory_program_low_usd'])}–{mo(e['mandatory_program_high_usd'])}. Freight, tax and an unapproved example contingency remain separate. No bids, actual payments, procurement promises or approvals have been invented.</p><p>PDF phases run through week 72 from overall project start, with closeout afterward. Construction roughly spans project weeks 22–72; actual dates and lead times are unknown. The earlier ranch's 21–37 week hired-crew estimate is superseded. All work is delegated; there is no owner DIY savings assumption.</p><div class="buttons"><a class="button" href="{prefix}materials/costs.html">Material / labor / professional breakdown</a><a class="button secondary" href="{prefix}project/index.html">Phase plan and gate status</a></div></section><section><p class="eyebrow">04 / IMPORTANT RECONCILIATIONS</p><h2>Do not turn assumptions into approvals.</h2><div class="grid"><div><h3>Before any field release</h3><ul><li>Obtain APN, exact zoning, survey, soils, water/septic and opt-out/permit/disclosure records.</li><li>Commission coordinated stamped structural/roof/envelope/egress design and private inspection scope.</li><li>Obtain insurer acceptance, three bids per trade, two PC/glulam quotes, written delivery dates and warranties.</li></ul></div><div><h3>Two corrections to the written sequence</h3><ul><li>Full backfill requires engineered temporary restraint or the accepted permanent roof/diaphragm restraint system. HP6 alone is not a structural release.</li><li>County guidance says Option 2 has no Certificate of Occupancy and retains an administrative final site visit. Other agency approvals and code duties still apply.</li></ul></div></div><p>All nine PDF hold points are recorded as unverified. Weekly reports, contact logs and cash/bid trackers are prepared locally; no calls, emails, applications, payments, supplier orders or construction have been performed.</p><a href="{prefix}project/brief-reconciliation.md">Owner brief reconciliation</a> · <a href="{prefix}project/requirements-matrix.csv">Requirements matrix</a> · <a href="{prefix}project/index.html">Primary sources and controls</a></section><section id="files"><p class="eyebrow">05 / CURRENT FILES & HISTORY</p><h2>Current owner revision.</h2><div class="download-list"><a href="{prefix}model/Owner-Earthship.blend">Blender V2<small>New native model, four scenes and timeline</small></a><a href="{prefix}materials/bill-of-materials.csv">Native quantity takeoff<small>Measured vs reservation, US units</small></a><a href="{prefix}materials/us-purchasing-and-costs.csv">US purchasing / cost CSV<small>Supplier references and allowances</small></a><a href="{prefix}materials/trade-labor.csv">Trade labor CSV<small>Person-hours, crew sizes, billed rates</small></a><a href="{prefix}project/hold-points.csv">Hold-point register<small>All nine gates await evidence</small></a><a href="{prefix}project/phase-cash-tracker.csv">Phase cash tracker<small>No actual / paid figures invented</small></a><a href="{prefix}project/decision-register.csv">Decisions and open evidence<small>Three brief choices confirmed</small></a><a href="https://github.com/shusain/portal-earthship-home-design/tree/0bfb490bcc7c7243a7f34b08109b511e1aeab222">Superseded ranch study<small>Prior plans/model/costs preserved in Git</small></a></div><p class="small">Raw owner PDF is retained locally, not uploaded. Its SHA256 is recorded with the public requirements digest; personal identity and source contact scripts are omitted.</p></section><footer>Portal Earthship Home Design · Owner brief V2 · Concept / not for construction · All images preserve intrinsic proportions</footer></main></body></html>'''
    (ROOT/'index.html').write_text(home,encoding='utf-8')
    # Old bookmarks must clearly lead to current requirements rather than an obsolete budget.
    redirect='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=../revisions/owner-brief-v2/materials/costs.html"><title>Cost report superseded</title><p>The ranch estimate is superseded. <a href="../revisions/owner-brief-v2/materials/costs.html">Open current owner-brief construction report</a>.</p></html>'
    (ROOT/'materials/costs.html').write_text(redirect,encoding='utf-8')
    (ROOT/'review/index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../index.html"><title>Current owner revision</title><p><a href="../index.html">Open current owner-brief design overview</a>. The earlier ranch study is superseded.</p></html>',encoding='utf-8')
    print('OWNER SITE BUILT: root overview, project controls, current report redirects, montage and animation')
